/**
 * 「关于“暗网动画”原楼主」评论区微调
 * 1. 22L 的「这里」可点击，跳转到「找一部在暗网上看过的离奇动画」
 * 2. 58L 的文字在每个「。」处另起一段
 * 3. 60L 的文字按原文分段
 */
Storage.ready().then(async function () {
  var FORMAT_KEY = 'originalPosterCommentFormat_v1';

  var OLD_58 = "暗网管理员（原蒙德网警）2012年在家中浴室割腕身亡。蒲公英（原蒙德刑警）2017年在警察局厕所饮枪身亡。骑兵管理员（原蒙德网警）2017年在浴室跳楼身亡。蛇蛇故事猫（原挪德卡莱人口数据库管理员）2020年在公共卫生间自缢，目前处于昏迷脑死亡状态。";
  var NEW_58 = "暗网管理员（原蒙德网警）2012年在家中浴室割腕身亡。\n\n蒲公英（原蒙德刑警）2017年在警察局厕所饮枪身亡。\n\n骑兵管理员（原蒙德网警）2017年在浴室跳楼身亡。\n\n蛇蛇故事猫（原挪德卡莱人口数据库管理员）2020年在公共卫生间自缢，目前处于昏迷脑死亡状态。";
  var NEW_60 = "当我找到的时候，我就意识到，我也会被诅咒。\n\n以下为视频语音转文字：如果让我从头开始说，那么事情从1999年起。我来爷爷工作的地下研究所休假。\n\n我们家不是住在城市里的，因为家里人都信奉霜月女神，这是我们挪德卡莱这边才有的信仰。但是我比较好玩，我不太信这个。但是这些都不太重要了。\n\n其实那边说是实验所，其实是个监狱，收容了很多奇奇怪怪的东西。千禧年之前的挪德卡莱是个很混乱的地带，当然，现在也差不多。这种黑监狱经常做点什么人体实验，和药物研发公司签约了，可以谋取大量利益，时至今日我想起来都觉得有点不适。\n\n我当时在那下面其实也没干什么，很无聊很黑很阴森，坐落在一个岛上。地下有七层，我每天住在三层，玩爷爷买回来的游戏机和看电视上的动漫。我现在都记得那个监狱，他中间是空的，每一层都有大大小小的牢房，最中间的那个大场地是犯人日常活动的地方，如果有人死掉了，可以通过电梯运送到地上，那个地方现在正好就是北地的坟茔。\n\n我第一次去见克里洛，是我爷爷派我从通风管道爬进去。给我的任务呢也很简单，就是和他聊聊天，看他会不会说话。医疗间是白色的，但是很黑，他病床旁边有一盏小灯，我把灯打开，就看到他了。\n\n那个时候他还带着呼吸机，脖子上插着静脉插管，他蓝黑色的头发和我差不多长，耳朵上订着那种我在农场看到牲畜才会订的名牌。没有活人是这个脸色也没有活人会是这个体温。\n\n但是他还活着。\n\n其实我有点害怕，但是我装成我根本无所畏惧的样子，他盯着我，我也盯着他，就在赌谁先说话。\n\n当然是他先说话了。他喊我小姐，我那个时候才12岁，大家都把我当成毛都没长齐的丫头，他恭恭敬敬喊了我一声小姐。\n\n所以我其实挺喜欢他的。\n\n这场对话并没有进行多久就被打断了，我被抓到审讯室。他们都说我现在很温和，其实我12岁的时候不仅脾气大而且什么都不怕。当时枪口就顶在我的后脑勺，他们问我他给我说了什么，我说，说了他以前军队的事情。\n\n其实我的胡编乱造根本没有什么用，因为世界上有一种东西叫做监控。然而我爷爷是这里还把他当作一个人来看待的，一切都是因为他的努力，他说我可以撬开那玩意儿的嘴巴，两百万买回来的东西，你们真的不想物尽其用吗？\n\n他们当然想了。所以我在这边休假也有了暑假作业，我要陪他说话，撬开他的嘴巴。这是一件很轻松的事情，因为我只需要带着游戏机进去在他面前翘着二郎腿打马里奥，或者是和他一起看动漫。他们给了我很多动漫带子，他就被绑在床上看我打游戏看我看动漫看我画画。他的眼睛是金黄色的，在黑暗待太久了有点像退化的鱼。我问他到底能不能看清，他很有礼貌地摇摇头说我看不清小姐。\n\n于是我就坐在他病床旁边画画，他也很安静地用那双不属于人类世界的眼睛看着我画画，偶尔很有礼貌地请求我把灯调亮一点。他很正常，我觉得他正常的不可思议。爷爷测过他的骨龄，他只有18岁。我就给他说你其实18岁。\n\n他咦了一声，说记不清了，反正年年都一样。\n\n我记得有一次，我从带子里面拿出来一卷动漫叫堕天使之城。那个挺恐怖的，我看的往他那边缩。但是那些血腥的镜头对于他却没有什么影响，他说这有什么大不了的，不就是把脑袋切开了吗？我也切开过。\n\n我说那很疼吧。\n\n他说痛都痛过了，记不清了，反正过两个月头发就长回来。他说血最多也不能放一个浴缸吧，里面肯定加水了，反正我没放这么多。\n\n他又说，你怎么了小姐，为什么用这种眼神看着我。\n\n我说，因为正常人不应该这种反应。\n\n他很谦肯地向我取经——那么正常人应该是什么反应。\n\n我说他们会呕吐悲伤，也许等你以后出去了，你要学会这样的情绪。\n\n我知道这句话是在安慰他，他其实这辈子都出不去。爷爷说了，他身上没有几个好的器官，也找不到几块属于自己的骨头。他也许是罗马尼亚人，一出生就在孤儿院等待着卖到实验室，现在他的国家和军队都分崩离析了，他肯定也活不久。\n\n说真的，我在那个时候真的把那个叫克里洛的实验体当朋友，他尊重我，会真诚地说希望你以后走到更远的地方。我渐渐也不会害怕他，我也挺喜欢在他面前画画的，底下六层看不见光，他只会温和地让我把灯调亮一点，然后说一些不合时宜的奇怪幽默笑话，其实大多数都不好笑，但是我很喜欢和他聊外面和未来。他总是说想起蒙德找蓝眼睛的小狗，哦不，小男孩。\n\n但是他过了一会儿又说算了，太无聊了，我想就这么睡下去也好。我说好啊，你睡吧，我要继续看动漫了。\n\n1999年11月份的时候，我那天带着画板想要去找他，但是我发现有些事情不太一样，有很多医疗人员进去，还有狱警拿着枪走进去，他们把我拦在外边，不让我去看。我后来才知道他在咬掉一个医疗人员的喉咙，血流了一地，他挣扎着翻滚到地上，大家赶过来的时候他很虔诚地被反绑着双手趴在地上舔舐着地面上的血液。\n\n于是我想起来，他的的确确不算是人类。这让我脊梁骨发凉。\n\n再后来我爷爷辞职了，我也离开故乡去上学了。那段时间的记忆在我脑海中逐渐模糊，我只知道，就像是帝国也会分崩离析一样，战争也会席卷挪德卡莱。你们没有在这边的边境待过，不太理解，战争是常有的事情。他们会毁掉监狱，也会建立起新的工厂，新的城市会拔地而起，而像克里洛这样的旧时代的不算人类的产物，在我脑海里他早点死了。\n\n毕竟他也说了，死亡对于他来说也算是陷入了无梦的安眠，也算是解脱。\n\n2012年，我回到挪德卡莱建设故乡，我只在森林里，远离城市的地方。夜晚我在家里打开了论坛，刷完了原楼主所有的帖子，然后我点进去了烛光灵的账号，我发现那是我的画。\n\n然而我只是当作巧合，我刷到CG杂图我也觉得是巧合，直到我看到了照片，我分不清他是人还是鬼，他就在电脑里静静看着我，和我童年的记忆重叠。\n\n但是我还是在想，长得像的人常有，更何况你有新名字了，你叫克里洛·楚德米洛维奇·菲林斯。你是从小到大都娇生惯养的至冬贵族，考上了列宾美院，以前是高级军官，现在是光鲜亮丽的教授。\n\n你切掉了四分之一个胃，肾脏肝脏全是人工的，身体里没有一块完整的骨骼属于自己，心脏毒性已经高了好几倍，大脑记忆区域受损，精神极度不稳定。你是被评估的残次品根本不能活过三年。\n\n然而十二年后你竟然还披着一张更像人的人皮活着。\n\n其实当我看到你的词条的时候，我就知道到底发生什么事了。菲林斯是冬都的贵族，而克里洛连自己家乡都不知道在哪里。菲林斯是美院的教授，但是你连书都没有读过。他十八岁的时候去了前线，但是你十八岁还被困在挪德卡莱的监狱。\n\n我想我已经知道了问题的答案，但是我还是不想确认，还是不敢确认。\n\n因为我刷到论坛的时候我发现你和心爱的人结婚了，他说你过的很好，我真心实意为年少时的朋友过的好而高兴。\n\n但是我很快发现事情好像不太对劲，也超出了我的预期。\n\n你没有回复我的消息，我以为你不想，但是我逐渐发现事情已经完全超出了我的预料。因为我发现无论在哪里你都不能算作一个人，你很多事情都没有学会，也理解不了。\n\n第一个死掉的人是蒙德的网警，他好像是第一个找到那一部动漫的人，看完就自杀了。\n\n第二个人也是蒙德的网警和刑警，当时我们在调查这件事情，他们打开了你丈夫和他哥哥的电脑，于是他们是其次看到那部动漫的人。\n\n他们也自杀了。\n\n这是当着我们的面。\n\n于是我找到了挪德卡莱知道最多故事的人奈芙尔，我最终还是下定决心给她讲述了我隐藏许久的故事。我不是想要毁掉你的生活，而是我觉得你根本没过上你想要的生活。我知道那个动画是你画的，我也知道其实你骨子里平等地憎恨这个世界上一切的人和事，但是你报复的都是无辜的人，我不明白为什么。\n\n于是我和奈芙尔开始找你，但是那个叫法尔伽的人把你藏的很好，我们根本找不到你。今年的时候，奈芙尔给那个叫法尔伽的人发邮件，他终于回复了，他说你们回到了挪德卡莱，如果真的是你的旧友，可以一起吃个饭，叙叙旧。\n\n然而你还是没有来。\n\n那个金毛在饭桌上和我和奈芙尔嘻嘻哈哈，推杯换盏，他看起来比以前的照片老了，我猜测你也一样。于是我问起了你，他说你生病了，更多的他不想提。\n\n我问他想不想听一个故事，他说可以听，但是也许，我可以讲一些他不知道的故事。于是我说不出口了。因为我在猜测，我猜测你们在一起这么多年，他也许早就知道。但是我还是忍不下心，万一他不知道，我说出这个没有百分之百把握的猜测，会不会把你好不容易回去的家毁掉。\n\n就算是这一刻我还是在念旧情，因为我看得出来法尔伽在说你名字的时候眼睛会微微眯起来，这样他看起来有点沧桑的脸一下子就温柔下来。\n\n法尔伽说他的梦想是当一个好丈夫和好父亲，也许1999年那个被关押的东西他根本不关心。他还说起那个动漫，他故作惊讶的样子说，啊那是年轻时候随手发的东西，你们还在关心吗？\n\n我说怎么会不关心呢？你不觉得奇怪吗？为什么自己的下属徒弟都自杀了？\n\n法尔伽还是笑嘻嘻地说，人生总是这样没有办法。\n\n他笑的有点假，但是我和奈芙尔也没有办法，我们见不到菲林斯。\n\n走的时候法尔伽一边点烟一边含混地说，下次等他病好了，一起出来，在海边找一个餐厅，晒晒太阳，聊聊天。\n\n可是还会有下次吗？我不知道也不确定。因为奈芙尔给我说，她觉得法尔伽有很大的问题，她想去查一下。可是我再次见到她是在医院，她只留给我两份传真。\n\n我想，她一定是找到了什么看到了什么。\n\n于是昨天夜晚，我登录了奈芙尔的账号去找最后一块儿拼图，我在搜索栏输入了菲林斯的名字去寻找最后一块儿拼图，因为我感觉我能坚持到我现在没有疯，全撑着一口气。我看到那个叫菲林斯的家伙的照片的时候，这个困扰我多年的猜想终于落地了，克里洛，我终于明白了。\n\n你们长得很像但是总有些东西是改变不了的，他是人而你还没有学会怎么成为人。你平等地憎恨着这个世界每一个人，我不知道你怎么做到的，我也不相信月亮上或者世界上有神明，但是我无比明确一切一定是因为你的诅咒。（笑）\n\n那么恭喜你，你已经报复很多人了，其实过去伤害过你的人都死了，但是你还不满意。\n\n我现在会割开我的手腕，我知道你在挪德卡莱，我也知道你在看这个视频，你有十分钟的时间来找我，我们墓里见。\n\n（黑屏）\n\n……";

  function norm(text) {
    return String(text || '').replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
  }

  function findTargetPost() {
    var posts = Storage.getPosts();
    for (var i = 0; i < posts.length; i++) {
      if (posts[i].title.indexOf('原楼主') !== -1 &&
          posts[i].title.indexOf('暗网动画') !== -1) {
        return posts[i];
      }
    }
    return null;
  }

  async function formatComments() {
    if (localStorage.getItem(FORMAT_KEY)) return;
    var target = findTargetPost();
    if (!target) return;

    var comments = Storage.getComments();
    var changed = false;
    comments.forEach(function (c) {
      if (c.postId !== target.id) return;
      var text = norm(c.content);
      if (text === norm(OLD_58)) {
        c.content = NEW_58;
        changed = true;
      } else if (text.length > 1000 && text.indexOf('当我找到的时候，我就意识到') === 0) {
        c.content = NEW_60;
        changed = true;
      }
    });

    if (changed) await Storage.saveComments(comments);
    localStorage.setItem(FORMAT_KEY, '1');
  }

  await formatComments();

  // 22L「这里」跳转到原帖
  var origShowPostDetail = App.showPostDetail;
  App.showPostDetail = function () {
    var result = origShowPostDetail.apply(this, arguments);
    decorateThisPost();
    return result;
  };

  function decorateThisPost() {
    var detailEl = document.querySelector('.post-detail');
    if (!detailEl) return;
    var titleEl = detailEl.querySelector('.post-detail-title');
    if (!titleEl) return;
    var title = titleEl.textContent || '';
    if (title.indexOf('原楼主') === -1 || title.indexOf('暗网动画') === -1) return;

    var target = null;
    var posts = Storage.getPosts();
    for (var i = 0; i < posts.length; i++) {
      if (posts[i].title.indexOf('找一部在暗网上看过的离奇动画') !== -1 &&
          posts[i].title.indexOf('该帖记录') === -1 &&
          posts[i].title.indexOf('该帖整理') === -1) {
        target = posts[i];
        break;
      }
    }
    if (!target) return;

    var items = detailEl.querySelectorAll('.comment-item');
    for (var k = 0; k < items.length; k++) {
      var floorEl = items[k].querySelector('.comment-floor');
      if (!floorEl || floorEl.textContent.trim() !== '22L') continue;

      var contentEl = items[k].querySelector('.comment-content');
      if (!contentEl || contentEl.dataset.hereLinked === '1') continue;
      if (contentEl.textContent.indexOf('这里') === -1) continue;

      contentEl.dataset.hereLinked = '1';
      contentEl.innerHTML = contentEl.innerHTML.replace(
        '这里',
        '<a href="#" class="original-post-link here-link" style="color:#8A5A3B;text-decoration:underline;cursor:pointer;">这里</a>'
      );

      var link = contentEl.querySelector('.here-link');
      if (link) {
        link.addEventListener('click', function (e) {
          e.preventDefault();
          e.stopPropagation();
          App.showPostDetail(target.id);
          window.scrollTo(0, 0);
        });
      }
    }
  }
});
